// mascote: um bichinho na faixa acima do prompt que reage aos eventos da sessão.
// Demonstra: banda AbovePrompt, estado reativo (atoms), timer e $.store.

import { atom, read, update } from 'claude-code'
import type { EngineInterface, Register } from 'claude-code'

import type { Mood } from '../types'
import { activity, FRAMES, isAnimating, moodAfter, NAP_AFTER_MS, subject, viewFor, BURST_MS } from './lib'

type $ = EngineInterface

const DEFAULT_NAME = 'Clawd'
const view = atom({ plugin: 'mascote', key: 'view' } as const, viewFor('idle', DEFAULT_NAME, 0))
const frame = atom({ plugin: 'mascote', key: 'frame' } as const, 0)
const name = atom({ plugin: 'mascote', key: 'name' } as const, DEFAULT_NAME)
const isHidden = atom({ plugin: 'mascote', key: 'isHidden' } as const, false)

const COLOR: Record<Mood, string> = {
  idle: 'cyan',
  thinking: 'yellow',
  working: 'yellow',
  celebrating: 'green',
  scared: 'red',
  proud: 'magenta',
  sleeping: 'gray',
}

// Há um turno rodando: aí o mascote nunca cochila, por mais que o modelo demore.
let isTurnRunning = false

async function setMood($: $, mood: Mood, detail = ''): Promise<void> {
  const next = viewFor(mood, await read($, name), await $.clock.now(), detail)
  await update($, view, () => next)
  await update($, frame, () => 0)
}

/**
 * Um único relógio para tudo: avança o quadro só enquanto o humor anima
 * (fora disso não escreve nada, então nada é redesenhado) e põe o mascote
 * para dormir depois de 2 minutos sem turno.
 */
async function tick($: $): Promise<void> {
  const v = await read($, view)
  const now = await $.clock.now()
  if (!isTurnRunning && v.mood !== 'sleeping' && now - v.since > NAP_AFTER_MS) {
    await setMood($, 'sleeping')
    return
  }
  if (isAnimating(v, now)) await update($, frame, n => n + 1)
}

export const register: Register = on => {
  on('session.start', async ($, e, next) => {
    await $.command.register({
      name: 'mascote',
      description: 'Mostra, esconde ou dá nome ao mascote',
      argumentHint: '[on|off|nome <novo nome>]',
    })
    // O nome fica no $.store: vale para todas as sessões, não só esta.
    const saved = await $.store.get('name')
    if (typeof saved === 'string' && saved !== '') await update($, name, () => saved)
    await setMood($, 'idle')
    $.clock.every(700, () => void tick($))

    return next(e)
  })

  on('turn.start', async ($, e, next) => {
    isTurnRunning = true
    await setMood($, 'thinking')

    return next(e)
  })

  on('tool.call', async ($, e, next) => {
    // Subagentes trabalham em paralelo; o mascote acompanha só o agente principal.
    if (e.agentId !== undefined) return next(e)
    const input = e as unknown as Record<string, unknown>

    // Uma comemoração recém-começada não é atropelada pela próxima ferramenta.
    const v = await read($, view)
    const isFresh = ['celebrating', 'scared', 'proud'].includes(v.mood) && (await $.clock.now()) - v.since < BURST_MS
    if (!isFresh) await setMood($, 'working', activity(e.tool, input))

    const ran = await next(e)
    const isError = ran.deny !== undefined || ran.isError === true
    await setMood($, moodAfter(e.tool, input, isError), subject(e.tool, input))

    return ran
  })

  on('turn.complete', async ($, e, next) => {
    if (e.agentId !== undefined) return next(e)
    isTurnRunning = false
    // O resultado do turno (comemorando, assustado, orgulhoso) fica na tela; o resto volta a esperar.
    const { mood } = await read($, view)
    if (e.reason === 'error') await setMood($, 'scared', 'o turno')
    else if (mood === 'thinking' || mood === 'working') await setMood($, 'idle')

    return next(e)
  })

  on('command.run', { command: 'mascote' }, async ($, e) => {
    const [action = '', ...rest] = e.args.trim().split(/\s+/)
    if (action === 'off') {
      await update($, isHidden, () => true)
      return { text: 'Mascote escondido. /mascote on traz de volta.' }
    }
    if (action === 'nome' && rest.length > 0) {
      const newName = rest.join(' ').slice(0, 20)
      await $.store.set('name', newName)
      await update($, name, () => newName)
      await setMood($, 'celebrating')
      return { text: `Agora o mascote se chama ${newName}.` }
    }
    await update($, isHidden, () => false)

    return { text: `${await read($, name)} está aqui.` }
  })

  on('ui.render', { component: 'AbovePrompt' }, async ($, e, next) => {
    if (e.props.hasSurvey || (await read($, isHidden))) return next(e)
    const { Box, Button, Text } = $.ui.resolve(e)
    const v = await read($, view)
    const frames = FRAMES[v.mood]
    const face = frames[(await read($, frame)) % frames.length] ?? frames[0]

    return (
      <Box gap={1}>
        <Text color={COLOR[v.mood]} bold>
          {face}
        </Text>
        <Text dimColor wrap="truncate-end">
          {await read($, name)}: {v.line}
        </Text>
        <Button key="hide" label="Esconder" plain dimColor onPress={() => update($, isHidden, () => true)} />
      </Box>
    )
  })
}

