// Lógica pura do mascote: humores, quadros e frases. Sem `$`, para testar fácil.

import type { Mood, MascotView } from '../types'

/** Dois (ou três) quadros por humor: o timer alterna entre eles. */
export const FRAMES: Record<Mood, readonly string[]> = {
  idle: ['(•‿•)'],
  thinking: ['(・_・ )', '( ・_・)'],
  working: ['(•_•)>', '(•_•)>>'],
  celebrating: ['\\(^o^)/', '/(^o^)\\'],
  scared: ['(°□°)!', '(°□°)!!'],
  proud: ['(⌐■_■)'],
  sleeping: ['(-_-) z', '(-_-) z z', '(-_-) z z z'],
}

/** Humores que animam enquanto durarem; os outros animam só por uns segundos. */
const LOOPING = new Set<Mood>(['thinking', 'working', 'sleeping'])
export const BURST_MS = 4_000
export const NAP_AFTER_MS = 2 * 60_000

export function isAnimating(view: MascotView, now: number): boolean {
  if (FRAMES[view.mood].length < 2) return false

  return LOOPING.has(view.mood) || now - view.since < BURST_MS
}

const TEST = /\b(?:(?:npm|pnpm|yarn|bun)\s+(?:run\s+)?test|npx\s+(?:vitest|jest)|vitest|jest|pytest|go\s+test|cargo\s+test)\b/
const SHIP = /\bgit\s+(?:-\S+\s+)*(commit|push)\b/

export function isTestCommand(command: string): boolean {
  return TEST.test(command)
}

/** Os dois últimos pedaços do caminho: "src/x.ts" diz mais que o caminho inteiro. */
export function shortPath(path: unknown): string {
  return String(path ?? '').split('/').filter(Boolean).slice(-2).join('/')
}

/** O que o agente está fazendo, em palavras do mascote. */
export function activity(tool: string, input: Record<string, unknown>): string {
  const command = String(input.command ?? '').split('\n')[0] ?? ''
  switch (tool) {
    case 'Read':
      return `lendo ${shortPath(input.file_path)}`
    case 'Edit':
    case 'Write':
    case 'NotebookEdit':
      return `editando ${shortPath(input.file_path ?? input.notebook_path)}`
    case 'Bash':
      return `rodando ${command.length > 40 ? `${command.slice(0, 39)}…` : command}`
    case 'Grep':
    case 'Glob':
      return `procurando "${String(input.pattern ?? '')}"`
    case 'WebFetch':
    case 'WebSearch':
      return 'pesquisando na web'
    case 'Agent':
      return 'chamando reforços (subagente)'
    default:
      return `usando ${tool.replace(/^mcp__/, '').replace(/__/g, ' › ')}`
  }
}

/** De quem é a culpa quando dá erro: o comando ou o arquivo, curto. */
export function subject(tool: string, input: Record<string, unknown>): string {
  if (tool === 'Bash') return String(input.command ?? '').split(/\s+/).slice(0, 3).join(' ')
  if (input.file_path !== undefined) return shortPath(input.file_path)

  return tool
}

/** O humor depois que uma ferramenta termina: comemora teste, assusta com erro, orgulha com commit. */
export function moodAfter(tool: string, input: Record<string, unknown>, isError: boolean): Mood {
  const command = tool === 'Bash' ? String(input.command ?? '') : ''
  if (isError) return 'scared'
  if (isTestCommand(command)) return 'celebrating'
  if (SHIP.test(command)) return 'proud'

  return 'thinking'
}

export function lineFor(mood: Mood, name: string, detail = ''): string {
  switch (mood) {
    case 'idle':
      return `${name} está pronto para o próximo pedido`
    case 'thinking':
      return 'hmm, deixa eu pensar…'
    case 'working':
      return `${detail}…`
    case 'celebrating':
      return 'testes passando! 🎉'
    case 'scared':
      return detail === '' ? 'eita, algo deu errado!' : `eita, ${detail} falhou!`
    case 'proud':
      return 'commit no ar, que orgulho'
    case 'sleeping':
      return 'me chama quando precisar'
  }
}

export function viewFor(mood: Mood, name: string, now: number, detail = ''): MascotView {
  return { mood, line: lineFor(mood, name, detail), since: now }
}

