export type Mood = 'idle' | 'thinking' | 'working' | 'celebrating' | 'scared' | 'proud' | 'sleeping'

/** O que o mascote mostra: o humor, a frase e desde quando está assim. */
export type MascotView = { mood: Mood; line: string; since: number }

declare module 'claude-code' {
  interface PluginState {
    mascote: {
      view: MascotView
      /** Quadro da animação; só muda enquanto o humor anima. */
      frame: number
      name: string
      isHidden: boolean
    }
  }
}
